public interface ParkingAssignmentStrategy {
    ParkingSpot findSpot(VehicleType vehicleType, List<Level> levels);
}

public enum VehicleType {
    MOTORCYCLE, CAR, TRUCK
}

public abstract class Vehicle {
    private String licensePlate;
    private VehicleType type;
    // constructor, getters, setters
}

public class ParkingTicket {
    private String ticketId;
    private LocalDateTime entryTime;
    private ParkingSpot spot;
    private boolean isPaid;
}

public class ParkingLot {
    private static ParkingLot instance;
    private List<Level> levels;
    private ParkingAssignmentStrategy assignmentStrategy;

    private ParkingLot() {
        this.levels = new ArrayList<>();
        this.assignmentStrategy = new NearestToEntranceStrategy();
    }

    public static synchronized ParkingLot getInstance() {
        if (instance == null) {
            instance = new ParkingLot();
        }
        return instance;
    }

    public synchronized ParkingTicket assignTicket(Vehicle vehicle) {
        ParkingSpot spot = assignmentStrategy.findSpot(vehicle.getType(), levels);
        if (spot == null) {
            throw new ParkingFullException("Parking lot is full.");
        }
        spot.assignVehicle(vehicle);
        return new ParkingTicket(UUID.randomUUID().toString(), LocalDateTime.now(), spot);
    }
}
